export interface CollectionLogItem {
  id: number;
  name: string;
}
export interface CollectionLogPage {
  name: string;
  items: CollectionLogItem[];
}
export interface CollectionLogTab {
  name: string;
  pages: Record<string, CollectionLogPage>;
}

/*
 * RuneScape 3 collection log.
 *
 * RS3's in-game logs are the Boss collection log, the Slayer collection log and
 * the Treasure Trail collection log (https://runescape.wiki/w/Collection_log).
 * The Bosses and Slayer tabs mirror those wiki logs' entries (page names are the
 * wiki's section names, which are the in-game log entries). Clues mirrors the
 * Treasure Trail log's per-tier reward sections (main uniques, not every casket
 * filler item). RS3 has no minigame log, so the Minigames tab is app-curated:
 * one page per MINIGAMES_LIST entry with its signature RS3 rewards. Other holds
 * RS3 journal collections (Menaphos/Arc journals) and skilling pets.
 *
 * IDs are generated as: (TAB_ID * 100000) + (PAGE_ID * 1000) + ITEM_ID
 * TAB IDs: Bosses=1, Slayer=2, Clues=3, Minigames=4, Other=5
 */

/**
 * Bosses-tab pages whose RS3 log name differs from the unlock table, or which
 * cover several BOSSES_LIST entries. Each maps a log page -> the BOSSES_LIST
 * entry/entries that unlock it. Shared by the consistency tests and
 * utils/collogReach.ts.
 */
export const BOSS_PAGE_ALIASES: Record<string, string[]> = {
  'Araxxi': ['Araxxor'],
  'Barrows': ['Barrows Brothers'],
  'Rise of the Six': ['Barrows: Rise of the Six'],
  'Hermod, the Spirit of War': ['Hermod'],
  'Nex, Angel of Death': ['Nex: Angel of Death'],
  'Rasial, the First Necromancer': ['Rasial'],
  'The Gate of Elidinis': ['Gate of Elidinis'],
  'TzTok-Jad and Har-Aken': ['TzHaar Fight Cave', 'Har-Aken'],
  'Rex Matriarch: Osseous': ['Rex Matriarchs'],
};

/**
 * Real RS3 boss-log pages for bosses that are not (yet) in BOSSES_LIST — newer
 * releases (Dec 2025 / Mar 2026). Kept for log parity and treated as
 * baseline-available until they get an unlock-table entry; once added to
 * BOSSES_LIST, remove them from here.
 */
export const COLLOG_ONLY_BOSS_PAGES = new Set<string>([]);

